package com.jh.knowledgeos.common;
public class ApiResponse<T>{private boolean success;private String message;private T data;public ApiResponse(){}public ApiResponse(boolean s,String m,T d){success=s;message=m;data=d;}public static <T> ApiResponse<T> ok(T d){return new ApiResponse<T>(true,"成功",d);}public static <T> ApiResponse<T> fail(String m){return new ApiResponse<T>(false,m,null);}public boolean isSuccess(){return success;}public String getMessage(){return message;}public T getData(){return data;}public void setSuccess(boolean v){success=v;}public void setMessage(String v){message=v;}public void setData(T v){data=v;}}
